const norm = (s: string) =>
  s
    .toLowerCase()
    .replace(/[^a-z0-9 ]/g, " ")
    .replace(/\s+/g, " ")
    .trim();

export function searchCities(query: string, limit = 8): City[] {
  const q = norm(query);
  if (!q) return [];
  const starts: City[] = [];
  const contains: City[] = [];
  for (const c of CITIES) {
    const n = norm(c.n);
    if (n.startsWith(q)) starts.push(c);
    else if (n.includes(q) || norm(c.b).startsWith(q)) contains.push(c);
    if (starts.length >= limit) break;
  }
  return [...starts, ...contains].slice(0, limit);
}

export function findCity(name: string): City | undefined {
  const q = norm(name);
  return CITIES.find((c) => norm(c.n) === q);
}

export type DetectedZone = "within_city" | "same_province" | "cross_province";

/** Same serving branch => within city, same province => same province, else cross province. */
export function detectZone(origin: City, destination: City): DetectedZone {
  if (norm(origin.b) === norm(destination.b)) return "within_city";
  if (origin.p === destination.p) return "same_province";
  return "cross_province";
}
